#include "script_editor.h"
#include "event_tools.h"
#include <QtWidgets>
namespace cf {
World &ScriptEditor::world(){return areaIndex>0?project.areas[areaIndex-1]:project.world;}
void ScriptEditor::edit(const std::function<void(Project &,World &)> &fn){if(filling)return;auto p=project;fn(p,areaIndex>0?p.areas[areaIndex-1]:p.world);if(onEdit)onEdit(p);}
ScriptEditor::ScriptEditor(QWidget *parent):QWidget(parent){
    auto *root=new QHBoxLayout(this);auto *side=new QVBoxLayout;side->addWidget(new QLabel("AREA"));areas=new QComboBox;side->addWidget(areas);actors=new QListWidget;side->addWidget(actors,1);
    auto *add=new QPushButton("+ Enemy / character"),*remove=new QPushButton("Remove actor");side->addWidget(add);side->addWidget(remove);auto *sw=new QWidget;sw->setLayout(side);sw->setMaximumWidth(300);root->addWidget(sw);
    auto *center=new QVBoxLayout;auto *controls=new QGroupBox("Game controls");auto *cf=new QFormLayout(controls);interact=new QComboBox;close=new QComboBox;restart=new QComboBox;inventory=new QComboBox;
    for(auto *combo:{interact,close,restart,inventory})for(auto pair:{qMakePair(QString("A"),16),qMakePair(QString("B"),32),qMakePair(QString("Select"),64),qMakePair(QString("Start"),128)})combo->addItem(pair.first,pair.second);
    cf->addRow("Interact / choose",interact);cf->addRow("Close / back",close);cf->addRow("Restart position",restart);cf->addRow("Inventory / switch container",inventory);center->addWidget(controls);
    auto *properties=new QFormLayout;name=new QLineEdit;sprite=new QComboBox;x=new QSpinBox;y=new QSpinBox;properties->addRow("Name",name);properties->addRow("Sprite",sprite);properties->addRow("Spawn X (tile)",x);properties->addRow("Spawn Y (tile)",y);center->addLayout(properties);
    templates=new QComboBox;templates->addItems({"top_down","patrol","chase","idle"});auto *apply=new QPushButton("Use template");auto *tr=new QHBoxLayout;tr->addWidget(new QLabel("Template"));tr->addWidget(templates,1);tr->addWidget(apply);center->addLayout(tr);
    script=new QPlainTextEdit;script->setFont(QFontDatabase::systemFont(QFontDatabase::FixedFont));center->addWidget(behaviorTools(script,[this]{return project;},[this]{return actorIndex<0;}),1);status=new QLabel;status->setWordWrap(true);center->addWidget(status);
    auto *help=new QLabel("Commands: behavior top_down / patrol / chase / idle\nspeed 1–2 (pixels per update) · every 1–8 (frames per update)\naxis x / y · range 1–255 px · sight 1–255 px\non_touch <prompt ID> or none · # starts a comment\n\nPlayer and enemies use an 8×8 foot box against the collision layer.\nPatrols reverse at walls; chase uses a Manhattan sight radius.\nContact prompts have a one-second cooldown. Animation bindings: animation idle, on_move walk, on_idle idle, on_interact attack.");help->setWordWrap(true);center->addWidget(help);root->addLayout(center,1);
    auto *promptHelp=new QLabel;QString instructions="PROMPT IDS\n\n";promptHelp->setObjectName("promptIds");promptHelp->setAlignment(Qt::AlignTop);promptHelp->setMinimumWidth(220);root->addWidget(promptHelp);
    connect(areas,&QComboBox::activated,this,[this](int i){areaIndex=i;actorIndex=-1;setProject(project);});
    connect(actors,&QListWidget::currentRowChanged,this,[this](int i){if(!filling){actorIndex=i-1;fillActor();}});
    connect(add,&QPushButton::clicked,this,[this]{if(world().actors.size()>=4){QMessageBox::information(this,"Actor limit","Use up to four actors per area, within the 40-sprite hardware budget.");return;}edit([&](Project &,World &w){Actor a;a.id="actor_"+QUuid::createUuid().toString(QUuid::Id128);a.name="New enemy";a.sprite=w.player;a.script=behaviorTemplate("patrol");a.x=qMin(w.spawnX+3,w.width-1);a.y=w.spawnY;w.actors<<a;actorIndex=w.actors.size()-1;});});
    connect(remove,&QPushButton::clicked,this,[this]{if(actorIndex>=0)edit([&](Project &,World &w){w.actors.removeAt(actorIndex);actorIndex=-1;});});
    connect(name,&QLineEdit::textEdited,this,[this](QString s){if(actorIndex>=0)edit([&](Project &,World &w){w.actors[actorIndex].name=s;});});
    connect(sprite,&QComboBox::activated,this,[this](int i){edit([&](Project &,World &w){if(actorIndex<0)w.player=sprite->itemData(i).toString();else w.actors[actorIndex].sprite=sprite->itemData(i).toString();});});
    auto position=[this]{edit([&](Project &,World &w){if(actorIndex<0){w.spawnX=x->value();w.spawnY=y->value();}else{w.actors[actorIndex].x=x->value();w.actors[actorIndex].y=y->value();}});};connect(x,&QSpinBox::valueChanged,this,position);connect(y,&QSpinBox::valueChanged,this,position);
    connect(script,&QPlainTextEdit::textChanged,this,[this]{if(filling)return;edit([&](Project &,World &w){if(actorIndex<0)w.playerScript=script->toPlainText();else w.actors[actorIndex].script=script->toPlainText();});});
    connect(apply,&QPushButton::clicked,this,[this]{QString kind=templates->currentText();if((actorIndex<0)!=(kind=="top_down")){QMessageBox::information(this,"Choose a matching template","Use top_down for the player; patrol, chase or idle for other actors.");return;}edit([&](Project &,World &w){if(actorIndex<0)w.playerScript=behaviorTemplate(kind);else w.actors[actorIndex].script=behaviorTemplate(kind);});});
    for(auto *combo:{interact,close,restart,inventory})connect(combo,&QComboBox::activated,this,[this]{edit([&](Project &p,World &){p.controls={interact->currentData().toInt(),close->currentData().toInt(),restart->currentData().toInt(),inventory->currentData().toInt()};});});
}
void ScriptEditor::setProject(const Project &p){filling=true;project=p;areaIndex=qBound(0,areaIndex,p.areas.size());actorIndex=qBound(-1,actorIndex,world().actors.size()-1);areas->clear();for(auto &w:p.allAreas())areas->addItem(w.chapter+" / "+w.name);areas->setCurrentIndex(areaIndex);actors->clear();actors->addItem("Player");for(auto &a:world().actors)actors->addItem(a.name);actors->setCurrentRow(actorIndex+1);interact->setCurrentIndex(interact->findData(p.controls.interact));close->setCurrentIndex(close->findData(p.controls.close));restart->setCurrentIndex(restart->findData(p.controls.restart));inventory->setCurrentIndex(inventory->findData(p.controls.inventory));QString ids="PROMPT IDS\n\n";for(auto &node:p.prompts)ids+=node.title+"\n"+node.id+"\n\n";findChild<QLabel *>("promptIds")->setText(ids);filling=false;fillActor();}
void ScriptEditor::fillActor(){filling=true;auto &w=world();bool player=actorIndex<0;name->setEnabled(!player);QString display=player?"Player":w.actors[actorIndex].name;if(name->text()!=display)name->setText(display);sprite->clear();for(auto &a:project.assets)if(a.kind=="sprite")sprite->addItem(a.name,a.id);sprite->setCurrentIndex(sprite->findData(player?w.player:w.actors[actorIndex].sprite));x->setRange(0,w.width-1);y->setRange(0,w.height-1);x->setValue(player?w.spawnX:w.actors[actorIndex].x);y->setValue(player?w.spawnY:w.actors[actorIndex].y);QString text=player?w.playerScript:w.actors[actorIndex].script;if(script->toPlainText()!=text)script->setPlainText(text);BehaviorSpec b;QString error;bool valid=parseBehavior(text,b,error);if(valid)templates->setCurrentIndex(b.code.kind==1?0:b.code.kind==2?1:b.code.kind==3?2:3);status->setText(valid?"✓ Script parsed. Test the area to run it.":error);filling=false;}
}
